             {'path': 'App/QuestifyMotion.swift',
              'status': 'M',
              'before_sha256': '7eed1ac98f0590e469dd9d2222ad0b315a99b0d65b845bc5365b5bdee6f740f3',
              'before_blob': '83ef3d73f067b3458eee577c7cb2afd020522951',
              'after_sha256': '813fbbcbaa0b3f35d5b132c706494b243e797151a5a9b2c5ff3cf54ba2e2fa90',
              'after_blob': 'b789bcdff9df491e07b3aba27a6db1747719ebe9',
              'hunks': [{'before': 'import SwiftUI\n'
                                   '\n'
                                   '/// System preference is read-only. A DEBUG-only policy input exercises '
                                   'our custom\n'
                                   '/// animation fallback without pretending to change iOS accessibility '
                                   'settings.\n'
                                   '@propertyWrapper\n'
                                   'struct QuestifyReduceMotion: DynamicProperty {\n'
                                   '    init() {}\n'
                                   '    @Environment(\\.accessibilityReduceMotion) private var systemValue\n'
                                   '    #if DEBUG\n'
                                   '    private static let '
                                   'fixtureValue=ProcessInfo.processInfo.arguments.contains("--uitesting-reduce-motion")\n'
                                   '    #endif\n'
                                   '    var wrappedValue:Bool {\n'
                                   '        #if DEBUG\n'
                                   '        return systemValue || Self.fixtureValue\n'
                                   '        #else\n'
                                   '        return systemValue\n'
                                   '        #endif\n'
                                   '    }\n'
                                   '}\n',
                         'after': 'import SwiftUI\n'
                                  '\n'
                                  '/// System preference is read-only. The local setting may reduce app '
                                  'motion further,\n'
                                  '/// but turning it off cannot override iOS. DEBUG can still force the '
                                  'existing fallback.\n'
                                  '@propertyWrapper\n'
                                  'struct QuestifyReduceMotion: DynamicProperty {\n'
                                  '    init() {}\n'
                                  '    @Environment(\\.accessibilityReduceMotion) private var systemValue\n'
                                  '    @AppStorage(ReducedMotionPreference.storageKey) private var '
                                  'localValue = ReducedMotionPreference.defaultValue\n'
                                  '    #if DEBUG\n'
                                  '    private static let '
                                  'fixtureValue=ProcessInfo.processInfo.arguments.contains("--uitesting-reduce-motion")\n'
                                  '    #endif\n'
                                  '    var wrappedValue:Bool {\n'
                                  '        #if DEBUG\n'
                                  '        return ReducedMotionPreference.effective(system: systemValue, '
                                  'local: localValue) || Self.fixtureValue\n'
                                  '        #else\n'
                                  '        return ReducedMotionPreference.effective(system: systemValue, '
                                  'local: localValue)\n'
                                  '        #endif\n'
                                  '    }\n'
                                  '}\n'}]},
