                                  '    '
                                  "b'Ql~V+&&o}VUu{0AkdEqFgXE3|gOxlOh$e_8h$e_8h$e_8h$e_8h$e_8h-Qgs*1^4%ng9<44+Rf(@z4+F{|{(<V7v'\n"
                                  ", '0951535392e893a74dcad525d5a9f81756d4c4076825b29f412318eef89e90df')\n"
                                  '\n'
                                  'def _club_inverse(raw, row, path):\n'
                                  "    require(isinstance(raw, bytes), 'Club source input must be complete "
                                  "bytes: ' + path)\n"
                                  "    require(digest(raw) == row['after_sha256'], 'Unknown complete club "
                                  "current input: ' + path)\n"
                                  "    require(row['before_sha256'] is not None, 'New club source has no "
                                  "historical predecessor: ' + path)\n"
                                  '    return _inverse_exact(raw, row, path)\n'
                                  '\n'
                                  '\n'
                                  'def _club_readiness(raw, *, current_only=False, preserve_pin=False):\n'
                                  '    pins = re.findall(rb"(?m)^CONTRACT_SHA256 = \'([0-9a-f]{64})\'$", '
                                  'raw)\n'
                                  '    if len(pins) != 1:\n'
                                  "        raise ValueError('Unknown complete club readiness pin')\n"
                                  '    normalized = raw.replace(pins[0], CLUB_PRE_CONTRACT_SHA256.encode(), '
                                  '1)\n'
                                  '    if digest(normalized) != CLUB_RUNNER_AFTER_NORMALIZED_SHA256:\n'
                                  '        if not current_only:\n'
                                  '            return raw\n'
                                  "        raise ValueError('Changed complete current club readiness "
                                  "source')\n"
                                  '    value = normalized\n'
                                  '    for hunk in reversed(CLUB_RUNNER_HUNKS):\n'
                                  "        after, before = hunk['after'].encode(), hunk['before'].encode()\n"
                                  '        if value.count(after) != 1:\n'
                                  "            raise ValueError('Missing/repeated complete club readiness "
                                  "inverse span')\n"
                                  '        value = value.replace(after, before, 1)\n'
                                  '    if digest(value) != CLUB_PRE_SHA256[RUNNER_PATH]:\n'
                                  "        raise ValueError('Complete published e2b readiness source not "
                                  "restored')\n"
                                  '    if preserve_pin:\n'
                                  '        value = value.replace(CLUB_PRE_CONTRACT_SHA256.encode(), pins[0], '
                                  '1)\n'
                                  '    return value\n'
                                  '\n'
                                  '\n'
                                  'def club_current_readiness_source(raw):\n'
                                  '    """Require the complete new postimage before restoring its '
                                  'member-copy body."""\n'
                                  '    return _club_readiness(raw, current_only=True, preserve_pin=True)\n'
                                  '\n'
                                  '\n'
                                  'def club_readiness_source(raw):\n'
                                  '    """Historical reader only: exact new body or unchanged native '
                                  'historical input."""\n'
                                  '    return _club_readiness(raw, preserve_pin=True)\n'
                                  '\n'
                                  '\n'
                                  'def _club_category_preimage(raw):\n'
                                  "    marker = b'\\n# Exact e2b P045 public-member route predecessor "
                                  "layer.\\n'\n"
                                  '    suffix = b"\\nif __name__ == \'__main__\':\\n    unittest.main()\\n"\n'
                                  "    require(digest(raw) == IMPLEMENTATION_SHA256, 'Changed complete club "
                                  "admission source')\n"
                                  "    require(raw.count(marker) == 1 and raw.endswith(suffix), 'Unknown "
                                  "club admission source boundary')\n"
                                  '    prefix, _ = raw.split(marker, 1)\n'
                                  '    for hunk in reversed(CLUB_PREFIX_HUNKS):\n'
                                  "        after, before = hunk['after'].encode(), hunk['before'].encode()\n"
                                  "        require(prefix.count(after) == 1, 'Missing/repeated club source "
                                  "interface span')\n"
                                  '        prefix = prefix.replace(after, before, 1)\n'
                                  '    slot = b"ADMISSION_FINGERPRINT = \'" + ADMISSION_FINGERPRINT.encode() '
                                  '+ b"\'"\n'
                                  "    require(prefix.count(slot) == 1, 'Unknown club admission fingerprint "
                                  "slot')\n"
                                  '    old = prefix.replace(slot, b"ADMISSION_FINGERPRINT = \'" + '
                                  'CLUB_PRE_FINGERPRINT.encode() + b"\'", 1) + suffix\n'
                                  "    require(digest(old) == CLUB_PRE_SHA256[SELF_PATH], 'Complete "
                                  "published e2b admission source not restored')\n"
                                  '    return old\n'
                                  '\n'
                                  '\n'
                                  'def club_predecessor_source(path, raw):\n'
                                  '    """Restore complete e2b bytes only; this function never admits a '
                                  'current root."""\n'
                                  '    if path in CLUB_PRE_SHA256 and digest(raw) == CLUB_PRE_SHA256[path]:\n'
                                  '        return raw\n'
                                  '    if path in CLUB_SOURCE_ROWS:\n'
                                  '        return _club_inverse(raw, CLUB_SOURCE_ROWS[path], path)\n'
                                  '    if path == RUNNER_PATH:\n'
                                  '        return _club_readiness(raw, current_only=True)\n'
                                  '    if path == SELF_PATH:\n'
                                  '        return _club_category_preimage(raw)\n'
                                  '    if path == PROFILE_PATH:\n'
                                  '        slot = b"DISCOVERY_HELPER_FINGERPRINT = \'" + '
                                  'ADMISSION_FINGERPRINT.encode() + b"\'"\n'
                                  "        require(raw.count(slot) == 1, 'Unknown club profile source pin')\n"
                                  '        old = raw.replace(slot, b"DISCOVERY_HELPER_FINGERPRINT = \'" + '
                                  'CLUB_PRE_FINGERPRINT.encode() + b"\'", 1)\n'
                                  "        require(digest(old) == CLUB_PRE_SHA256[path], 'Complete published "
                                  "e2b profile source not restored')\n"
                                  '        return old\n'
                                  '    if path == CATEGORY_GATE:\n'
                                  '        normalized, source = _decoded_external_template(raw)\n'
                                  "        require(source == (ROOT / SELF_PATH).read_bytes(), 'Unknown club "
                                  "complete external source template')\n"
                                  '        old_source = _club_category_preimage(source)\n'
                                  '        encoded = encode_frozen_source(old_source).decode()\n'
                                  "        first = b'\\n# CATEGORY_ROAM_FROZEN_SOURCE_BEGIN\\n'\n"
                                  "        last = b'# CATEGORY_ROAM_FROZEN_SOURCE_END\\n'\n"
                                  '        suffix = b"\\nif __name__ == \'__main__\':\\n    '
                                  'unittest.main()\\n"\n'
                                  '        old = normalized[:-len(suffix)] + first + '
                                  "b'FROZEN_REGISTRATION_SOURCE_ZLIB_BASE85 = (\\n' + b''.join(\n"
                                  "            ('    ' + repr(encoded[i:i+80]) + '\\n').encode() for i in "
                                  "range(0, len(encoded), 80)) + b')\\n' + last + suffix\n"
                                  "        require(digest(old) == CLUB_PRE_SHA256[path], 'Complete published "
                                  "e2b external template not restored')\n"
                                  '        return old\n'
                                  '    return raw\n'
                                  '\n'
                                  '\n'
                                  'def _club_restore_contract(value):\n'
                                  '    value = copy.deepcopy(value)\n'
                                  '    if digest(encode(value)) == CLUB_PRE_CONTRACT_SHA256:\n'
                                  '        return value\n'
                                  '    for path, descriptor in CLUB_FEATURE_ROWS.items():\n'
                                  "        row = value['feature_batch_sources'].get(path)\n"
                                  "        extension = descriptor['extension']\n"
                                  "        require(row is not None and row['after_sha256'] == "
                                  "extension['after_sha256'],\n"
                                  "                'Unknown club feature postimage: ' + path)\n"
                                  "        hunks = extension['hunks']\n"
                                  "        require(hunks and row['hunks'][-len(hunks):] == hunks, 'Changed "
                                  "exact club inverse extension: ' + path)\n"
                                  "        if descriptor['previous_row_sha256'] is None:\n"
                                  "            require(row == extension, 'Changed newly admitted club source "
                                  "row: ' + path)\n"
                                  "            del value['feature_batch_sources'][path]\n"
                                  '        else:\n'
                                  "            row['after_sha256'] = extension['before_sha256']\n"
                                  "            del row['hunks'][-len(hunks):]\n"
                                  '            require(digest(encode(row)) == '
                                  "descriptor['previous_row_sha256'], 'Original complete club source row not "
                                  "restored: ' + path)\n"
                                  '    for path, old in CLUB_SUPPORT_BEFORE.items():\n'
                                  "        require(path in value['feature_batch_support_sha256'], 'Missing "
                                  "club support registration: ' + path)\n"
                                  '        if old is None:\n'
                                  "            del value['feature_batch_support_sha256'][path]\n"
                                  '        else:\n'
                                  "            value['feature_batch_support_sha256'][path] = old\n"
                                  '    for key, descriptor in CLUB_CONTRACT_FIELDS.items():\n'
                                  "        require(key in value and value[key] == descriptor['current'], "
                                  "'Changed exact club contract field: ' + key)\n"
                                  "        if descriptor['absent_before']:\n"
                                  '            del value[key]\n'
                                  '        else:\n'
                                  "            value[key] = copy.deepcopy(descriptor['previous'])\n"
                                  "    require(digest(encode(value)) == CLUB_PRE_CONTRACT_SHA256, 'Complete "
                                  "published e2b central contract not restored')\n"
                                  '    return value\n'
                                  '\n'
                                  '\n'
                                  'def club_authenticate_current(raw, root):\n'
                                  '    """Read all six actual product files before any inverse or historical '
                                  'cache."""\n'
                                  '    root = Path(root).absolute()\n'
                                  "    require(not root.is_symlink() and root.resolve() == root, 'Symlinked "
                                  "or aliased club current root')\n"
                                  '    paths = tuple(CLUB_PRODUCT_SHA256) + tuple(path for path in '
                                  'CLUB_CURRENT_INPUTS if path not in CLUB_PRODUCT_SHA256)\n'
                                  '    contents = {}\n'
                                  '    for path in paths:\n'
                                  '        file = root / path\n'
                                  '        require(file.is_file() and not file.is_symlink() and '
                                  'file.resolve() == file,\n'
                                  "                'Missing, escaped or symlinked actual club current input: "
                                  "' + path)\n"
                                  '        contents[path] = file.read_bytes()\n'
                                  "    require(contents[CONTRACT_PATH] == raw, 'Actual club current contract "
                                  "differs from supplied bytes')\n"
                                  '    value = json.loads(raw)\n'
                                  "    require(encode(value) == raw, 'Noncanonical or duplicate club current "
                                  "contract')\n"
                                  '    for path, expected in CLUB_PRODUCT_SHA256.items():\n'
                                  "        require(digest(contents[path]) == expected, 'Changed actual club "
                                  "product: ' + path)\n"
                                  '    for path, row in CLUB_SOURCE_ROWS.items():\n'
                                  "        require(digest(contents[path]) == row['after_sha256'], 'Changed "
                                  "actual club support/source: ' + path)\n"
                                  '    runner = contents[RUNNER_PATH]\n'
                                  '    pins = re.findall(rb"(?m)^CONTRACT_SHA256 = \'([0-9a-f]{64})\'$", '
