                                  '                    if decorate is None:\n'
                                  "                        raise TypeError('Historical context manager is "
                                  "not a decorator')\n"
                                  '                    return decorate(*args, **kwargs)\n'
                                  '            proxy = ContextBoundary()\n'
                                  '            guarded_managers[id(value)] = (value, proxy)\n'
                                  '            guarded_managers[id(proxy)] = (proxy, proxy)\n'
                                  '            return proxy\n'
                                  '        # Returned closures, bound methods and callable objects may be '
                                  'invoked\n'
                                  '        # after their creating reader has exited. Preserve the raw '
                                  'boundary.\n'
                                  '        if callable(value) and not _club_inspect.isclass(value):\n'
                                  '            return guard_function(value)\n'
                                  '        return value\n'
                                  '\n'
                                  '    def guard_function(function):\n'
                                  '        saved = guarded_functions.get(id(function))\n'
                                  '        if saved is not None and saved[0] is function:\n'
                                  '            return saved[1]\n'
