                                  '\n'
                                  '\n'
                                  'def club_original_current_context(root=_CLUB_CURRENT_ROOT):\n'
                                  '    """Build/cache the finite physical e2b input only after '
                                  'actual-current checks."""\n'
                                  '    global _club_context_cache\n'
                                  '    root = _club_exact_current_root(root)\n'
                                  '    if _club_context_cache is not None:\n'
                                  '        _club_context_cache.verify()\n'
                                  '        return _club_context_cache\n'
                                  '    rows = _club_authenticate_raw(root, collect=True)\n'
                                  '    # Callers may set TMPDIR to an authorized RAM-backed location. No '
                                  'repository\n'
                                  '    # hardlinks, current fallback bytes, or broad repository copy are '
                                  'permitted.\n'
                                  "    life = _club_tempfile.TemporaryDirectory(prefix='club-e2b-reader-')\n"
                                  "    target = Path(life.name) / 'source'\n"
                                  '    try:\n'
                                  '        target.mkdir()\n'
                                  '        for relative, raw in rows.items():\n'
                                  '            destination = target / relative\n'
                                  '            destination.parent.mkdir(parents=True, exist_ok=True)\n'
                                  '            destination.write_bytes(raw)\n'
                                  '        if _club_tree_sha256(target) != _CLUB_E2B_SHA256:\n'
                                  "            raise ValueError('Exact finite e2b physical input differs')\n"
